import { useEffect, useRef } from 'react';
import { useInfiniteQuery, useQueryClient } from '@tanstack/react-query';
import { debounce, useVirtualizer } from '@tanstack/react-virtual';
import { Text } from '../ui/text';
import { Tweet } from './Tweet';
import { GroupedTweet } from './GroupedTweet';
import { LoadingIndicator } from './LoadingIndicator';
import { LOADER_HEIGHT, LoadPreviousTweets } from './LoadPreviousTweets';
import type { DBTweet } from '~/types/bluebird';
import { Box } from 'styled-system/jsx';

import type { TweetGroup } from '~/types/bluebird';

interface ReadingModeProps {
  lastReadTweetId?: string | null;
  onCurrentMonthYearChange: (monthYear: string | null) => void;
  readingModeType: 'normal' | 'grouped';
}

export const LOCAL_STORAGE_KEY = 'bluebirdReadingModeLastReadTweetId';
export const SCROLL_MARGIN = LOADER_HEIGHT;

export function ReadingMode({
  lastReadTweetId,
  onCurrentMonthYearChange,
  readingModeType
}: ReadingModeProps) {
  // eslint-disable-next-line react-compiler/react-compiler
  'use no memo';
  const queryClient = useQueryClient();
  const parentRef = useRef<HTMLDivElement>(null);
  const initialScrollDone = useRef(false); // New ref to track initial scroll

  const fetchTweets = async ({
    pageParam
  }: {
    pageParam?: { cursor?: string; direction?: 'before' | 'after' };
  }) => {
    const params = new URLSearchParams();

    if (pageParam?.cursor) {
      params.append('cursor', pageParam.cursor);
    }
    if (pageParam?.direction) {
      params.append('direction', pageParam.direction);
    }

    const response = await fetch(`/api/bluebird/reading?${params.toString()}`);
    const data: DBTweet[] = await response.json();
    return { tweets: data, pageParam };
  };

  const fetchGroupedTweets = async ({
    pageParam
  }: {
    pageParam?: { cursor?: string; direction?: 'before' | 'after' };
  }) => {
    const params = new URLSearchParams();

    if (pageParam?.cursor) {
      params.append('cursor', pageParam.cursor);
    }
    if (pageParam?.direction) {
      params.append('direction', pageParam.direction);
    }

    const response = await fetch(`/api/bluebird/reading/grouped?${params.toString()}`);
    const data: TweetGroup[] = await response.json();
    return { groupedTweets: data, pageParam };
  };

  const {
    data: normalTweetsData,
    fetchNextPage,
    fetchPreviousPage,
    hasNextPage,
    hasPreviousPage,
    isFetchingNextPage,
    isFetchingPreviousPage,
    isLoading: isLoadingNormalTweets,
    isError: isNormalTweetsError
  } = useInfiniteQuery({
    queryKey: ['readingModeTweets', lastReadTweetId],
    queryFn: fetchTweets,
    initialPageParam: {
      cursor: lastReadTweetId || '',
      direction: 'after' as const
    },
    getNextPageParam: (lastPage) => {
      if (lastPage.tweets.length === 0) return undefined;
      return {
        cursor: lastPage.tweets[lastPage.tweets.length - 1].id,
        direction: 'after' as 'before' | 'after'
      };
    },
    getPreviousPageParam: (firstPage, pages) => {
      if (firstPage.tweets.length === 0 && pages.length === 1 && lastReadTweetId) {
        return { cursor: lastReadTweetId, direction: 'before' as const };
      }
      if (firstPage.tweets.length === 0) return undefined;
      return { cursor: firstPage.tweets[0].id, direction: 'before' as const };
    },
    refetchOnWindowFocus: false,
    refetchOnMount: false,
    refetchOnReconnect: false,
    enabled: readingModeType === 'normal'
  });

  const {
    data: groupedTweetsData,
    fetchNextPage: fetchNextGroupedPage,
    fetchPreviousPage: fetchPreviousGroupedPage,
    hasNextPage: hasNextGroupedPage,
    hasPreviousPage: hasPreviousGroupedPage,
    isFetchingNextPage: isFetchingNextGroupedPage,
    isFetchingPreviousPage: isFetchingPreviousGroupedPage,
    isLoading: isLoadingGroupedTweets,
    isError: isGroupedTweetsError
  } = useInfiniteQuery({
    queryKey: ['readingModeGroupedTweets', lastReadTweetId],
    queryFn: fetchGroupedTweets,
    initialPageParam: {
      cursor: lastReadTweetId || '',
      direction: 'after' as const
    },
    getNextPageParam: (lastPage) => {
      if (lastPage.groupedTweets.length === 0) return undefined;
      return {
        cursor: lastPage.groupedTweets[lastPage.groupedTweets.length - 1].tweets[0].id,
        direction: 'after' as 'before' | 'after'
      };
    },
    getPreviousPageParam: (firstPage, pages) => {
      if (firstPage.groupedTweets.length === 0 && pages.length === 1 && lastReadTweetId) {
        return { cursor: lastReadTweetId, direction: 'before' as const };
      }
      if (firstPage.groupedTweets.length === 0) return undefined;
      return { cursor: firstPage.groupedTweets[0].tweets[0].id, direction: 'before' as const };
    },
    refetchOnWindowFocus: false,
    refetchOnMount: false,
    refetchOnReconnect: false,
    enabled: readingModeType === 'grouped'
  });

  const tweets = normalTweetsData?.pages.flatMap((page) => page.tweets) || [];
  const groupedTweets = groupedTweetsData?.pages.flatMap((page) => page.groupedTweets) || [];

  const isLoadingTweets = isLoadingNormalTweets || isLoadingGroupedTweets;
  const isError = isNormalTweetsError || isGroupedTweetsError;

  const virtualizer = useVirtualizer({
    count: readingModeType === 'normal' ? tweets.length : groupedTweets.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 250, // Estimate average item size
    overscan: 5,
    initialRect: initialScrollDone.current ? undefined : { height: 0, width: 0 } // Prevent initial scroll if restoring position
  });

  const virtualItems = virtualizer.getVirtualItems();

  useEffect(() => {
    initialScrollDone.current = false;
  }, []);
  // Effect to scroll to last read position on mount
  useEffect(() => {
    if (readingModeType === 'normal' && (!normalTweetsData || initialScrollDone.current)) return;
    if (readingModeType === 'grouped' && (!groupedTweetsData || initialScrollDone.current)) return;

    virtualizer.scrollToOffset(SCROLL_MARGIN);
    initialScrollDone.current = true;
  }, [lastReadTweetId, normalTweetsData, groupedTweetsData, virtualizer, readingModeType]);

  // Effect to fetch more data when scrolling near the ends
  useEffect(() => {
    if (!virtualItems.length) return;

    const lastItem = virtualItems[virtualItems.length - 1];

    if (readingModeType === 'normal') {
      if (lastItem.index === tweets.length - 1 && hasNextPage && !isFetchingNextPage) {
        fetchNextPage();
      }
    } else if (readingModeType === 'grouped') {
      if (
        lastItem.index === groupedTweets.length - 1 &&
        hasNextGroupedPage &&
        !isFetchingNextGroupedPage
      ) {
        fetchNextGroupedPage();
      }
    }
  }, [
    virtualItems,
    hasNextPage,
    isFetchingNextPage,
    fetchNextPage,
    tweets.length,
    hasNextGroupedPage,
    isFetchingNextGroupedPage,
    fetchNextGroupedPage,
    groupedTweets.length,
    readingModeType
  ]);

  // Effect to save current scroll position and update progress
  useEffect(() => {
    const scrollElement = parentRef.current;
    if (!scrollElement) return;

    const findClosestItemToTop = () => {
      const viewportTop = scrollElement.scrollTop;
      // Find the first item whose start position is greater than or equal to the viewportTop
      for (const item of virtualizer.getVirtualItems()) {
        if (item.start >= viewportTop) {
          return item;
        }
      }
      // If no item is found (e.g., at the very bottom), return the last item
      const virtualItems = virtualizer.getVirtualItems();
      return virtualItems.length > 0 ? virtualItems[virtualItems.length - 1] : null;
    };

    const handleScroll = () => {
      const closestItem = findClosestItemToTop();
      if (readingModeType === 'normal') {
        if (closestItem && tweets[closestItem.index]) {
          localStorage.setItem(LOCAL_STORAGE_KEY, tweets[closestItem.index].id);

          const tweet = tweets[closestItem.index];
          if (tweet.createdAt) {
            const date = new Date(tweet.createdAt);
            const monthYear = `${date.getFullYear()}-${(date.getMonth() + 1)
              .toString()
              .padStart(2, '0')}`;
            onCurrentMonthYearChange(monthYear);
          }
        }
      } else if (readingModeType === 'grouped') {
        if (closestItem && groupedTweets[closestItem.index]) {
          localStorage.setItem(LOCAL_STORAGE_KEY, groupedTweets[closestItem.index].tweets[0].id);

          const group = groupedTweets[closestItem.index];
          if (group.group_start_time) {
            const date = new Date(group.group_start_time);
            const monthYear = `${date.getFullYear()}-${(date.getMonth() + 1)
              .toString()
              .padStart(2, '0')}`;
            onCurrentMonthYearChange(monthYear);
          }
        }
      }
    };

    // Set initial progress
    handleScroll();

    const debouncedHandleScroll = debounce(window, handleScroll, 200);
    scrollElement.addEventListener('scroll', debouncedHandleScroll);

    return () => {
      scrollElement.removeEventListener('scroll', debouncedHandleScroll);
      // Save position on unmount
      if (readingModeType === 'normal') {
        const closestItem = findClosestItemToTop();
        if (closestItem && tweets[closestItem.index]) {
          localStorage.setItem(LOCAL_STORAGE_KEY, tweets[closestItem.index].id);
        }
      } else if (readingModeType === 'grouped') {
        const closestItem = findClosestItemToTop();
        if (closestItem && groupedTweets[closestItem.index]) {
          localStorage.setItem(LOCAL_STORAGE_KEY, groupedTweets[closestItem.index].tweets[0].id);
        }
      }
    };
  }, [
    virtualizer,
    tweets,
    groupedTweets,
    onCurrentMonthYearChange,
    queryClient,
    debounce,
    readingModeType
  ]);

  const handleFetchPreviousPage = () => {
    fetchPreviousPage().then(() => {
      setTimeout(() => {
        virtualizer.scrollToOffset(SCROLL_MARGIN);
      }, 10);
    });
  };

  const handleFetchPreviousGroupedPage = () => {
    fetchPreviousGroupedPage().then(() => {
      setTimeout(() => {
        virtualizer.scrollToOffset(SCROLL_MARGIN);
      }, 10);
    });
  };

  if (isLoadingTweets && (readingModeType === 'normal' ? !tweets.length : !groupedTweets.length)) {
    return <LoadingIndicator isLoading={isLoadingTweets} hasMore={true} />;
  }

  if (isError) {
    return <Text className="text-center mt-4">Error loading tweets.</Text>;
  }

  return (
    <Box ref={parentRef} height="calc(100vh - 64px)" overflowY="auto">
      {(readingModeType === 'normal' && (
        <LoadPreviousTweets
          loadPrevious={() => handleFetchPreviousPage()}
          hasPreviousPage={hasPreviousPage}
          isFetchingPreviousPage={isFetchingPreviousPage}
        />
      )) ||
        (readingModeType === 'grouped' && (
          <LoadPreviousTweets
            loadPrevious={() => handleFetchPreviousGroupedPage()}
            hasPreviousPage={hasPreviousGroupedPage}
            isFetchingPreviousPage={isFetchingPreviousGroupedPage}
          />
        ))}
      <Box style={{ height: `${virtualizer.getTotalSize()}px`, position: 'relative' }}>
        {virtualItems.map((virtualItem) => {
          if (readingModeType === 'normal') {
            const tweet = tweets[virtualItem.index];
            return (
              <Box
                key={virtualItem.key}
                data-index={virtualItem.index}
                ref={virtualizer.measureElement}
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  transform: `translateY(${virtualItem.start}px)`
                }}
              >
                {tweet ? (
                  <Tweet tweet={tweet.data} />
                ) : (
                  <LoadingIndicator isLoading={true} hasMore={true} />
                )}
              </Box>
            );
          } else {
            const group = groupedTweets[virtualItem.index];
            return (
              <Box
                key={virtualItem.key}
                data-index={virtualItem.index}
                ref={virtualizer.measureElement}
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  transform: `translateY(${virtualItem.start}px)`
                }}
              >
                {group ? (
                  <GroupedTweet group={group} />
                ) : (
                  <LoadingIndicator isLoading={true} hasMore={true} />
                )}
              </Box>
            );
          }
        })}
      </Box>
      <LoadingIndicator
        isLoading={
          isFetchingNextPage ||
          isFetchingPreviousPage ||
          isFetchingNextGroupedPage ||
          isFetchingPreviousGroupedPage
        }
        hasMore={hasNextPage}
      />
    </Box>
  );
}
