import { useEffect, useState } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { useTranslation } from 'react-i18next';
import { LOCAL_STORAGE_KEY, ReadingMode } from '~/components/bluebird/ReadingMode';
import { Box, Stack } from 'styled-system/jsx';
import { Text } from '~/components/ui/text';
import { Button } from '~/components/ui/button';
import { useBluebirdMonthsYears } from '~/hooks/useBluebirdMonthsYears';
import { RadioGroup } from '~/components/ui/radio-group';
import MainContentAndRightSidebar from '~/components/layout/MainContentAndRightSidebar';

export default function Page() {
  const [selectedMonthYear, setSelectedMonthYear] = useState<string | null>(null);
  const [currentMonthYear, setCurrentMonthYear] = useState<string | null>(null);
  const [lastReadTweetId, _setLastReadTweetId] = useState<string | null | undefined>(undefined);
  const [readingModeType, setReadingModeType] = useState<'normal' | 'grouped'>('grouped');

  const queryClient = useQueryClient();
  const { t, i18n } = useTranslation();

  const { data: monthsYearsData = [] } = useBluebirdMonthsYears();
  const monthsYears = monthsYearsData.sort((a, b) => a.monthYear.localeCompare(b.monthYear));

  useEffect(() => {
    _setLastReadTweetId(localStorage.getItem(LOCAL_STORAGE_KEY));
  }, []);

  useEffect(() => {
    if (selectedMonthYear) {
      const fetchFirstTweetId = async () => {
        const response = await fetch(
          `/api/bluebird/tweets/first-id-by-month?monthYear=${selectedMonthYear}`
        );
        const data = await response.json();
        const newLastReadTweetId = data.id;

        if (newLastReadTweetId) {
          _setLastReadTweetId(newLastReadTweetId);
          localStorage.setItem(LOCAL_STORAGE_KEY, newLastReadTweetId);
          queryClient.resetQueries({
            queryKey:
              readingModeType === 'grouped' ? ['readingModeGroupedTweets'] : ['readingModeTweets']
          });
        }
      };
      fetchFirstTweetId();
    }
  }, [selectedMonthYear, queryClient]);

  return (
    <MainContentAndRightSidebar
      rightSidebarContent={({ close }) => (
        <Stack h="full" p="4">
          <Box mt="4">
            <Text mb="2" fontWeight="bold">
              {t('bluebird.readingMode.months')}
            </Text>
            <Stack gap="1">
              {monthsYears.map((my) => (
                <Button
                  data-active={currentMonthYear === my.monthYear ? 'true' : undefined}
                  key={my.monthYear}
                  variant="ghost"
                  size="lg"
                  onClick={() => {
                    if (currentMonthYear !== my.monthYear) {
                      setSelectedMonthYear(my.monthYear);
                      close();
                    }
                  }}
                  justifyContent="flex-start"
                  _active={{ bg: 'bg.emphasized' }}
                >
                  {new Date(my.monthYear).toLocaleString(i18n.language, {
                    month: 'long',
                    year: 'numeric'
                  })}{' '}
                  <Text as="span" color="fg.subtle" fontSize="sm">
                    ({my.count})
                  </Text>
                </Button>
              ))}
            </Stack>
          </Box>
          <Box>
            <Text mb="2" fontWeight="bold">
              {t('bluebird.readingMode.mode')}
            </Text>
            <RadioGroup.Root
              value={readingModeType}
              onValueChange={(e) => setReadingModeType(e.value as 'normal' | 'grouped')}
            >
              <RadioGroup.Item value="grouped">
                <RadioGroup.ItemControl />
                <RadioGroup.ItemText>{t('bluebird.readingMode.grouped')}</RadioGroup.ItemText>
                <RadioGroup.ItemHiddenInput />
              </RadioGroup.Item>
              <RadioGroup.Item value="normal">
                <RadioGroup.ItemControl />
                <RadioGroup.ItemText>{t('bluebird.readingMode.normal')}</RadioGroup.ItemText>
                <RadioGroup.ItemHiddenInput />
              </RadioGroup.Item>
            </RadioGroup.Root>
          </Box>
        </Stack>
      )}
    >
      {lastReadTweetId !== undefined && (
        <ReadingMode
          lastReadTweetId={lastReadTweetId}
          onCurrentMonthYearChange={setCurrentMonthYear}
          readingModeType={readingModeType}
        />
      )}
    </MainContentAndRightSidebar>
  );
}
